-- ============================================================
-- 机房巡检系统 菜单初始化（RuoYi-Vue-Plus v6）
-- sys_menu 共 22 列，INSERT 必须严格按列顺序提供 22 个值
-- 列顺序: menu_id, menu_name, parent_id, order_num, path, component,
--         query_param, is_frame, is_cache, menu_type, visible, status,
--         perms, icon, active_menu, ext, create_dept, create_by,
--         create_time, update_by, update_time, remark
--
-- ID 号段（本模块独占 1770000000000000010 ~ 1770000000000000199，共 36 个节点）:
--   M 目录 : 1770000000000000010
--   C 菜单 : 1770000000000000101 / 1770000000000000102 / 1770000000000000103 / 1770000000000000104 / 1770000000000000105 / 1770000000000000106 / 1770000000000000107
--   F 按钮 : 菜单ID + 10*(序号+1)，各模块号段:
--            1770000000000000111-1770000000000000151 / 1770000000000000112-1770000000000000152 / 1770000000000000113-1770000000000000163 / 1770000000000000114-1770000000000000154 / 1770000000000000115-1770000000000000145 / 1770000000000000117-1770000000000000137
--
-- 本脚本可重复执行：先清理本号段的菜单与角色关联，再重新插入
-- ============================================================

-- 清理旧数据（含 sys_role_menu 关联），保证幂等
DELETE FROM sys_role_menu WHERE menu_id BETWEEN 1770000000000000010 AND 1770000000000000199;
DELETE FROM sys_menu      WHERE menu_id BETWEEN 1770000000000000010 AND 1770000000000000199;

