-- 角色授权：按 role_key 关联超级管理员（v6 的 role_id 并非 1，硬编码会授权失效）
-- 如需授权给其它角色，改 role_key 即可；去掉 WHERE 则授权给全部角色
INSERT INTO sys_role_menu (role_id, menu_id)
SELECT r.role_id, m.menu_id
FROM sys_role r
CROSS JOIN sys_menu m
WHERE r.role_key = 'superadmin'
  AND m.menu_id BETWEEN 1770000000000000010 AND 1770000000000000199;

